const item = $input.first();
const message = item.json.message?.text || "";

const regex = /^@n8n_slack\s+(newsletter|news\s*letter|news|letter)\s+(.+)/i;
const match = message.match(regex);

const topic = (match && match[2].trim())
  ? match[2].trim().replace(/\s+/g, " ")
  : null;

// Merge input + new field
return {
  ...item.json,
  topic: topic
};

const item = $input.first();

// Helpers
function formatDate(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr);
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short"
  });
}

function freshness(dateStr) {
  if (!dateStr) return "";
  const now = new Date();
  const d = new Date(dateStr);
  const diff = (now - d) / (1000 * 60 * 60 * 24);

  if (diff <= 1) return "🔴 Breaking";
  if (diff <= 3) return "🟠 Recent";
  if (diff <= 7) return "🟡 This Week";
  return "⚪ Earlier";
}

// Extract values


const name = $('Code in JavaScript').first().json.message.chat.first_name                    || "there";
const topic = item.json.topic || "Global News";
const logo = item.json.logo || "";
const articles = item.json.articles || [];

// ⭐ Top Story
const top = articles[0];

const topStoryHTML = top ? `
  <div style="background:#F8FAFC; border:1px solid #E2E8F0; padding:14px; border-radius:6px; margin-bottom:14px;">
    <div style="font-size:11px; font-weight:600; color:#0B3D91;">⭐ TOP STORY</div>

    <div style="font-size:16px; font-weight:700; color:#1F4E79;">
      ${top.title || ""}
    </div>

    <div style="font-size:12px; color:#666;">
      ${freshness(top.publishedAt)} ${formatDate(top.publishedAt)} • ${top.source || ""}
    </div>

    <div style="font-size:13px; color:#333; margin-top:6px;">
      ${(top.description || "").slice(0, 180)}
    </div>

    <a href="${top.url || "#"}" style="font-size:12px; color:#0B3D91; text-decoration:none;">
      Read full story →
    </a>
  </div>
` : "";

// Remaining news
const newsHTML = articles.slice(1, 5).map((a, i) => `
  <tr>
    <td style="padding:10px 0; border-bottom:1px solid #eee;">

      <div style="font-size:14px; font-weight:600; color:#1F4E79;">
        ${i + 2}. ${a.title || ""}
      </div>

      <div style="font-size:11px; color:#888;">
        ${freshness(a.publishedAt)} ${formatDate(a.publishedAt)} • ${a.source || ""}
      </div>

      <div style="font-size:13px; color:#333;">
        ${(a.description || "").slice(0, 120)}
      </div>

      <a href="${a.url || "#"}" style="font-size:12px; color:#0B3D91; text-decoration:none;">
        Read more →
      </a>

    </td>
  </tr>
`).join("");

// Final HTML
const html = `
<html>
<body style="font-family:Arial; background:#ffffff; margin:0; padding:0;">

<!-- Header -->
<div style="padding:12px; border-bottom:1px solid #eee; text-align:center;">
  ${logo ? `<img src="${logo}" style="height:40px;" />` : ""}
  <div style="font-size:15px; font-weight:600; color:#0B3D91;">
    AI Orchestrator — Executive Newsletter
  </div>
</div>

<!-- Container -->
<div style="max-width:600px; margin:auto; padding:12px;">

  <p style="font-size:14px;">Hi <b>${name}</b>,</p>

  <h3 style="color:#0B3D91; margin:6px 0;">
    ${topic}
  </h3>

  <p style="font-size:12px; color:#777; margin-bottom:12px;">
    ${new Date().toLocaleDateString("en-GB")}
  </p>

  ${topStoryHTML}

  <table width="100%" cellspacing="0" cellpadding="0">
    ${newsHTML}
  </table>

  <p style="font-size:11px; color:#aaa; margin-top:12px; text-align:center;">
    AI Orchestrator • Executive Intelligence Brief
  </p>

</div>

</body>
</html>
`;

// ✅ Final Output (preserve input + add newsletter)
return {
  ...item.json,
  newsletter: {
    content: html
  }
};

const items = $input.all();

return items.map(item => {
  let parsed;

  try {
    parsed = JSON.parse(item.json.output);
  } catch {
    parsed = {
      guardrail: true,
      llm: false,
      web_search: false,
      reason: "Invalid JSON"
    };
  }

  return {
    json: {
      decision: parsed
    }
  };
});

const items = $input.all();

return items.map(item => {
  let html = "";

  // Case 1: HTML is directly in json (string)
  if (typeof item.json === "string") {
    html = item.json;
  }
  // Case 2: HTML is in a field like 'content' or 'html'
  else if (item.json.content) {
    html = item.json.content;
  }
  else if (item.json.html) {
    html = item.json.html;
  }
  // Case 3: Entire object → stringify
  else {
    html = JSON.stringify(item.json);
  }

  return {
    json: {
      newsletter: {
        content: html
      }
    }
  };
});
